mapper.select:
SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.target AS target, doc.external_id AS externalId, doc.title AS title, doc.agency_name AS agencyName, doc.category_name AS categoryName, doc.source_date AS sourceDate, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, NULL AS pageNo, c.source_path AS sourcePath, c.source_url AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash FROM law_api_document_chunks c JOIN law_api_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y'
AND doc.target IN
#{target}
AND (
c.chunk_text LIKE CONCAT('%', #{keyword}, '%') OR c.chunk_title LIKE CONCAT('%', #{keyword}, '%') OR doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY CASE
WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 0 WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 1 WHEN c.chunk_text LIKE CONCAT('%', #{keyword}, '%') THEN 2
ELSE 3 END, doc.target, doc.title, c.sort_order LIMIT #{limit}

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.target AS target, doc.external_id AS externalId, doc.title AS title, doc.agency_name AS agencyName, doc.category_name AS categoryName, doc.source_date AS sourceDate, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, NULL AS pageNo, c.source_path AS sourcePath, c.source_url AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash FROM law_api_documents doc JOIN law_api_document_chunks c ON c.document_id = doc.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y'
AND doc.target IN
#{target}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY CASE
WHEN doc.title = #{keyword} THEN 0 WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 1 WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 2
ELSE 3 END, doc.target, doc.title, c.sort_order LIMIT #{limit}
